// config.js
// Equivalent to Java jamorham.keks.Config except includes Dexcom G7 KEKs
const Util = require('./util');

// Constant 2D arrays (mirroring byte[][] in Java)
const KEY1 = [
  Util.hexStringToByteArray('039503316070A26884ECD320106080A26884ECD330107030240040A08F620F921D6251ACB39895DB5C49AB30033E94D7E61C9EFE8F67107E3E0F5DC4E85FDB3EF05CCAA14C33C30D63F23D51F26A1624619087F06F06743031AEA9'),
  Util.hexStringToByteArray(''),
];

const KEY2 = [
  Util.hexStringToByteArray('039503316070A26884ECD320106080A26884ECD330107030240040840CCEF4364F4F87D6B0D58F393050FC0ED7301604CFF5F03EAFF546E5EDAC66E0359991C66A8C9F91DE3F4E7CFD4936E26C593835EFE80951A79AAAACC5B285'),
  Util.hexStringToByteArray(''),
];

// obtain these using the decodeG7QRCode.js module in utily
// they are listed in order, keks_p1, keks_p2, keks_p3 which is reverse of the order in the QR code
const KEKS = [
  Util.hexStringToByteArray(''),
  Util.hexStringToByteArray(''),
  Util.hexStringToByteArray('308187020100301306072a8648ce3d020106082a8648ce3d030107046d306b0201010420007cfbd596f6e74477b8c0e9f6f7a174275e101ef6bf7d18caf01181d127b579a144034200045118c35e9e41e7e0654fee801c52a9c5dfc510ef09597d5cca8461e4af9c666714834f2bc903f16fabfc45755b0183f1a09745cdffcb4e2f799e50bed9a6b58c'),
];

const REFERENCE_B = Util.hexStringToByteArray('1A808807F7E953C754A02E0D3C51FA2D2ED3D7699430A51D910D4FBCBA3EEF2F');
const ALICE_B = Util.hexStringToByteArray('36C69656E647');// "Client"
const BOB_B = Util.hexStringToByteArray('375627675627');// "7vkvkv"
const CMD1 = Buffer.from([0x0A]);
const SPARAMB = Buffer.from([0x02]);
const TIME_EXTENDEDB = Buffer.from([0x06, 0x19]);
const TIME_EXTENDED2B = Buffer.from([0xFF, 0x06, 0x01]);
const TIME_EXTENDED3B = Buffer.from([0x06, 0x00]);
const PREFIX_B = Buffer.from([0x30, 0x30]);
const ONE_GET_DATA_4E_CMD = Buffer.from([0x4e, 0x0a, 0xa9]);
const GET_DATA_4E_CMD = Buffer.from([0x4e]);
const CHALLENGE_OUTB = Buffer.from([0x0d, 0x00, 0x02]);

// Enum equivalent: a frozen object with byte[] values
const Get = Object.freeze({
  SPARAM: SPARAMB,
  TIME_EXTENDED: TIME_EXTENDEDB,
  TIME_EXTENDED2: TIME_EXTENDED2B,
  TIME_EXTENDED3: TIME_EXTENDED3B,
  PREFIX: PREFIX_B,
  KEYCMD: CMD1,
  KEY1A: KEY1[0],
  KEY1B: KEY1[1],
  KEY2A: KEY2[0],
  KEY2B: KEY2[1],
  ALICE: ALICE_B,
  BOB: BOB_B,
  REFERENCE: REFERENCE_B,
  GETDATA: ONE_GET_DATA_4E_CMD,
  GETDATA2: GET_DATA_4E_CMD,
  CHALLENGE_OUT: CHALLENGE_OUTB,
});

// Export everything as a single config object (mirroring static access in Java)
const Config = Object.freeze({
  KEY1,
  KEY2,
  KEKS,
  REFERENCE_B,
  ALICE_B,
  BOB_B,
  Get,
});

module.exports = Config;
